        // geo_country / geo_province -- single-sourced from RegionSeedData rather than duplicated
        // here as literal rows, so this and RegionSeeder/Region can never disagree about the list.
        // A subselect on geo_country.code resolves country_id: addSql() queues SQL for execution
        // after up() returns, so lastInsertId() immediately after an addSql() call would run before
        // that INSERT ever actually executed.
        $countrySortOrder = 0;
        foreach (RegionSeedData::COUNTRIES as $countryCode => $countryName) {
            $this->addSql(
                'INSERT INTO geo_country (code, name, status, sort_order) VALUES (:code, :name, :status, :sort_order)',
