            $provinceSortOrder = 0;
            foreach (RegionSeedData::PROVINCES[$countryCode] as $provinceCode => $provinceName) {
                $this->addSql(
                    'INSERT INTO geo_province (country_id, code, name, status, sort_order)
                     SELECT c.id, :code, :name, :status, :sort_order FROM geo_country c WHERE c.code = :country',
